import os

BASE = os.path.dirname(os.path.abspath(__file__))
os.chdir(BASE)
ACC, BOOKS, TRANS = "data/ACCOUNTS.DAT", "data/BOOKS.DAT", "data/TRANSACTIONS.DAT"
REC = 34


def read_records(path):
    with open(path, "rb") as f:
        data = f.read()
    return [bytearray(data[i:i + REC]) for i in range(0, len(data) - REC + 1, REC)], data[len(data) // REC * REC:]


def write_records(path, recs, tail=b""):
    with open(path, "wb") as f:
        for r in recs:
            f.write(bytes(r))
        f.write(tail)


def num(b):
    s = bytes(b).replace(b" ", b"0").decode("latin-1")
    try:
        return int(s)
    except ValueError:
        return 0


def main():
    with open("src/INPUT.DAT", "rb") as f:
        raw = f.read(22)
    if not raw:
        print("Error: Input file is empty")
        return
    raw = raw.ljust(22, b" ")
    buyer, seller, book = raw[0:4], raw[4:8], raw[8:12]
    amount = num(raw[12:22])

    accs, acc_tail = read_records(ACC)
    books, book_tail = read_records(BOOKS)
    bf = sf = kf = vo = False
    for r in accs:
        if r[0:4] == buyer:
            bf = True
        if r[0:4] == seller:
            sf = True
    for r in books:
        if r[0:4] == book:
            kf = True
            if r[24:28] == seller:
                vo = True
    print(" ")
    if not (bf and sf and kf and vo):
        print("Transaction failed due to validation errors")
        return

    def store(r, v):
        r[24:34] = str(abs(v) % 10**10).zfill(10).encode()

    for r in accs:
        if r[0:4] == buyer:
            store(r, num(r[24:34]) - amount)
        if r[0:4] == seller:
            store(r, num(r[24:34]) + amount)
    write_records(ACC, accs, acc_tail)
    for r in books:
        if r[0:4] == book:
            r[24:28] = buyer
    write_records(BOOKS, books, book_tail)
    with open(TRANS, "ab") as f:
        f.write(book + str(amount % 10**10).zfill(10).encode() + seller + buyer)
    print("Transaction completed successfully")


main()
